using System;using System.IO;using System.Text;using System.Linq;using System.Collections.Generic;using System.Globalization;using System.Windows.Forms;using ScoreModern.RecoveredFragments;
namespace ScoreModern {public sealed partial class Editor {
 enum DrawExportStage{None,Selection,Filename}
 DrawExportStage drawExportStage;List<int> drawExportItems;
 void StartDrawExport(string arguments){if(arguments=="0")arguments="";if(arguments.Length!=0){short diagnostic;if(!Int16.TryParse(arguments,NumberStyles.Integer,CultureInfo.InvariantCulture,out diagnostic))throw new NotSupportedException("DPY diagnostic controls require a verified signed16 integer.");if(diagnostic>0){ShowOriginalParameterArray();return;}if(diagnostic<0){ShowOriginalDisplayArray();return;}}drawExportStage=DrawExportStage.Selection;drawExportItems=null;Message("Enter a list of Item numbers to be saved as a DRAW vector list file."+Environment.NewLine+"Enter a number greater than the last item to save everything. (B=backup)");}
 bool SubmitDrawExport(string input){if(drawExportStage==DrawExportStage.None)return false;if(drawExportStage==DrawExportStage.Selection){string[] words=input.Split(new[]{' ','\t'},StringSplitOptions.RemoveEmptyEntries);if(words.Length==0||input.Trim().Equals("B",StringComparison.OrdinalIgnoreCase)){drawExportStage=DrawExportStage.None;drawExportItems=null;Message("");return true;}if(words.Length>24)throw new NotSupportedException("DPY input lists above24 entries require original retained-tail verification.");var selected=new List<int>();int tokenIndex=0;foreach(string word in words){int position=tokenIndex++;int n;if(!Int32.TryParse(word,NumberStyles.Integer,CultureInfo.InvariantCulture,out n)||n<0)throw new NotSupportedException("This DPY list control is awaiting original verification.");if(n==0)break;if(n>score.Items.Count){if(position!=words.Length-1)throw new NotSupportedException("DPY controls after a greater-than-last selector require verification.");int start=selected.Count==0?0:selected[selected.Count-1]+1;int remaining=Math.Min(Math.Max(0,score.Items.Count-start),32-selected.Count);selected.AddRange(Enumerable.Range(start,remaining));break;}selected.Add(n-1);}if(selected.Count==0){drawExportStage=DrawExportStage.None;drawExportItems=null;Message("");return true;}drawExportItems=selected;drawExportStage=DrawExportStage.Filename;if(NativeDiskDialogChoice.Files){string chosen=ChooseCommandFile("Save DPY vectors",true,"SCORE drawings (*.drw)|*.drw");if(chosen!=null)return SubmitDrawExport(chosen);drawExportStage=DrawExportStage.None;drawExportItems=null;Message("");return true;}Message("Enter filename ->");return true;}string name=input.Trim();if(name.Length==0)throw new NotSupportedException("The blank DPY filename is awaiting original verification.");string path=NativeOutputLocation.RequireWritableDestination(source,Path.GetFullPath(name));bool selectionHasPostScript=drawExportItems.Any(index=>score.Items[index].Code==15);int encodedEntries;byte[] contents=DrawVectorFile(drawExportItems,out encodedEntries);ScoreFileStorage.Write(path,contents);drawExportStage=DrawExportStage.None;drawExportItems=null;Message("*** Writing "+name+Environment.NewLine+(selectionHasPostScript?"*** PostScript program will not be used."+Environment.NewLine:"")+"Saving  c."+encodedEntries.ToString(CultureInfo.InvariantCulture).PadLeft(5)+" vectors.");return true;}
 byte[] DrawVectorFile(List<int> selection,out int encodedEntries){encodedEntries=0;canvas.LayoutScore();var dat=new NativeDatGlyphs(canvas.Library.Root,true);var cache=new NativeDatHeadCache();short font=0;var points=new List<PrimitiveTextPoint>();foreach(int itemIndex in selection){var item=score.Items[itemIndex];if(item.P(1)!=item.Code)throw new NotSupportedException("DPY fractional item code requires original verification.");if(item.Code==16||item.Code==15)continue;if(item.Code!=11&&item.Code!=15&&(item.P(19)!=0||item.P(20)!=0))throw new NotSupportedException("DPY retained working fields19/20 require original verification.");if(item.Code<1||item.Code>18)throw new NotSupportedException("DPY vector producer for Code "+item.Code+" is awaiting original export verification.");short next;if(item.Code==4||item.Code==5||item.Code==6){short? labelFont;points.AddRange(NativeScanDynamicVectors.Prepare(item,canvas.PageDocument.Contexts[item],canvas.Library.Root,canvas.TextLayout,out labelFont,true));if(labelFont.HasValue)font=labelFont.Value;continue;}points.AddRange(NativeDatDrawing.Prepare(item,canvas.PageDocument.Contexts[item],canvas.PageDocument,canvas.Library,canvas.TextLayout,dat,cache,font,out next));font=next;}var b=new StringBuilder();bool first=true;int ox=0,oy=0;foreach(var point in points){encodedEntries+=point.Operation>0?2:1;int x=NativeNotationContext.Word(point.X,true)/10,y=NativeNotationContext.Word(point.Y,false)/10;if(first){ox=x;oy=y;first=false;}b.Append((x-ox).ToString(CultureInfo.InvariantCulture).PadLeft(7)).Append((y-oy).ToString(CultureInfo.InvariantCulture).PadLeft(7)).Append(point.Operation.ToString(CultureInfo.InvariantCulture).PadLeft(4)).Append("\r\n");}if(encodedEntries>4000)throw new NotSupportedException("DPY exceeds the original4000-entry output limit; no file was written.");return Encoding.GetEncoding(437).GetBytes(b.ToString());}
 bool DrawExportKey(KeyEventArgs key){if(drawExportStage==DrawExportStage.None)return false;if(key.KeyCode==Keys.Escape){drawExportStage=DrawExportStage.None;drawExportItems=null;command.Clear();Message("");key.SuppressKeyPress=true;return true;}if(key.Control||key.Alt||key.KeyCode>=Keys.F1&&key.KeyCode<=Keys.F24){key.SuppressKeyPress=true;return true;}return false;}
}}
